update pb_ai.kb_chunks set chunk = $kb${"id": "osha-loi-trench-stacking-1", "state": "US", "tier": "core", "title": "OSHA letter: stacking trench boxes", "topic": "OSHA interpretation letters on trenches and manholes", "text": "OSHA letter of October 29, 1991, \"Stacking trench boxes in trenches.\" A trade association asked whether, when two trench boxes are stacked, the top box has to be rated for the full depth of the trench. OSHA's answer: stacked shields \"do not all have to be designed to resist the forces calculated for the deepest part of the trench.\" \"The standard only requires that the shields be used at a depth not greater than that for which they are designed.\" OSHA suggested a design feature or a marking system showing each shield's maximum depth so a lighter box does not end up on the bottom. In practice: stack only as the manufacturer's tabulated data allows, pin the boxes together as the data says, put the deeper-rated box at the bottom, and keep the data on site.", "source": "OSHA Standard Interpretation, 1991-10-29 (1926.650, 1926.652)", "url": "https://www.osha.gov/laws-regs/standardinterpretations/1991-10-29", "checked": "2026-11-20", "edition": "OSHA letter of interpretation, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2971 and chunk->>'id' = 'osha-loi-trench-stacking-1';
